intro:
Specialization of std::formatter that defines formatting rules for a std::chrono::zoned_time.

This formatter uses std::chrono::local_time_format for formatting.

The parse member is inherited from the base class.

Let tp be the formatting argument, ctx be the formatting context. The behavior of the format member is equivalent to

auto info = tp.get_info();
return std::formatter</*local-time-format-t*/>::format(
    std::local_time_format(tp.get_local_time(), &info.abbrev, &info.offset), ctx);

The std::formatter specialization is usually not directly accessed, but is used through formatting functions.

recommendedExamples.code:
#include <chrono>
#include <iostream>
#include <string_view>

int main() {
    using std::chrono_literals::operator""y;
    using std::operator""sv;

    std::cout << std::chrono::zoned_time{} << " : default\n";

    constexpr std::string_view location1{"America/Phoenix"sv};
    std::cout << std::chrono::zoned_time{location1} << " : " << location1 << '\n';

    const std::chrono::time_zone *timeZonePtr = std::chrono::locate_zone("UTC");
    std::cout << std::chrono::zoned_time{timeZonePtr} << " : UTC time zone\n";

    constexpr auto location2{"Europe/Rome"sv};
    std::cout << std::chrono::zoned_time{location2,
                     std::chrono::local_days{2021y / 12 / 31}}
              << " : " << location2 << '\n';

    constexpr auto location3{"Europe/Rome"sv};
    constexpr auto some_date =
        std::chrono::sys_time<std::chrono::days>{2021y / 12 / 31};
    std::cout << std::chrono::zoned_time{location3, some_date} << " : " << location3
              << '\n';

    const auto now =
        std::chrono::floor<std::chrono::minutes>(std::chrono::system_clock::now());
    constexpr auto location4{"Europe/Rome"sv};
    std::cout << std::chrono::zoned_time{location4, now} << " : " << location4 << '\n';

    constexpr auto NewYork{"America/New_York"sv};
    constexpr auto Tokyo{"Asia/Tokyo"sv};
    const std::chrono::zoned_time tz_Tokyo{Tokyo, now};
    const std::chrono::zoned_time tz_NewYork{NewYork, now};
    std::cout << std::chrono::zoned_time{Tokyo, tz_NewYork} << " : " << Tokyo << '\n';
    std::cout << std::chrono::zoned_time{NewYork, tz_Tokyo} << " : " << NewYork << '\n';
}
